class Dog:
    def __init__(self, name):
        self.name = name

d = Dog("Rex")
print(d.name)

class Dog:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return f"{self.name} says Woof!"

print(Dog("Rex").speak())

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

print(Rectangle(3, 4).area())

class Counter:
    def __init__(self):
        self.value = 0

    def increment(self):
        self.value += 1

c = Counter()
c.increment()
c.increment()
c.increment()
print(c.value)

class BankAccount:
    def __init__(self):
        self.balance = 0

    def deposit(self, x):
        self.balance += x

    def withdraw(self, x):
        self.balance -= x

acct = BankAccount()
acct.deposit(200)
acct.withdraw(50)
print(acct.balance)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"({self.x}, {self.y})"

print(Point(1, 2))

class Animal:
    def speak(self):
        return "..."

class Dog(Animal):
    def speak(self):
        return "Woof"

print(Animal().speak())
print(Dog().speak())

class Person:
    def __init__(self, name):
        self.name = name

class Student(Person):
    def __init__(self, name, school):
        super().__init__(name)
        self.school = school

s = Student("Asha", "Joy")
print(s.name, s.school)

class Square:
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side ** 2

class Rectangle:
    def __init__(self, w, h):
        self.w = w
        self.h = h

    def area(self):
        return self.w * self.h

for shape in [Square(2), Rectangle(3, 5)]:
    print(shape.area())
